","import React, { useState, useEffect } from "react";

interface Props {
 navigate: (view: string, extras?: { type?: string; id?: string }) => void;
 issueType: string | null;
}

function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

const CATEGORY_MAP: Record<string, string> = {
 overcrowding: "Overcrowded",
 "late-bus": "Bus Delay",
 "rude-driver": "Safety Concern",
 "broken-ac": "Vehicle Breakdown",
 "unsafe-driving": "Safety Concern",
 "dirty-bus": "Vehicle Breakdown",
 "missed-stop": "Bus Not Arrived",
 accessibility: "Accessibility Transportation Request",
 "route-change": "Route Change Request",
 noise: "Safety Concern",
 "broken-seat": "Vehicle Breakdown",
 other: "Bus Delay",
};

const SAFETY_CONCERN_MAP: Record<string, string> = {
 "rude-driver": "security_concern",
 "unsafe-driving": "unsafe_driving",
 noise: "security_concern",
};

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 Accept: "application/json",
 "Content-Type": "application/json",
 };
 const token = (window as any).g_ck;
 if (token) headers["X-UserToken"] = token;
 return headers;
}

export default function IssueFormScreen({ navigate, issueType }: Props) {
 const [routes, setRoutes] = useState<any[]>([]);
 const [buses, setBuses] = useState<any[]>([]);
 const [stops, setStops] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [submitting, setSubmitting] = useState(false);
 const [submitted, setSubmitted] = useState(false);
 const [createdCase, setCreatedCase] = useState<any>(null);
 const [error, setError] = useState("");

 // Form fields
 const [selectedRoute, setSelectedRoute] = useState("");
 const [selectedBus, setSelectedBus] = useState("");
 const [selectedStop, setSelectedStop] = useState("");
 const [description, setDescription] = useState("");
 const [severity, setSeverity] = useState("Medium");
 const [requestedRoute, setRequestedRoute] = useState("");
 const [requestedStop, setRequestedStop] = useState("");
 const [safetyConcernType, setSafetyConcernType] = useState("unsafe_driving");
 const [latitude, setLatitude] = useState<number | null>(null);
 const [longitude, setLongitude] = useState<number | null>(null);

 const issueTypeValue = CATEGORY_MAP[issueType || "other"] || "Bus Delay";
 const typeLabel = (issueType || "other").replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
 const isRouteChange = issueTypeValue === "Route Change Request";
 const isSafetyConcern = issueTypeValue === "Safety Concern";

 useEffect(() => {
 // Get geolocation
 if (navigator.geolocation) {
 navigator.geolocation.getCurrentPosition(
 (pos) => {
 setLatitude(pos.coords.latitude);
 setLongitude(pos.coords.longitude);
 },
 () => {}
 );
 }

 // Fetch reference data
 const fetchData = async () => {
 try {
 const [routesRes, busesRes, stopsRes] = await Promise.all([
 fetch("/api/now/table/u_route?sysparm_query=u_status=Active&sysparm_display_value=all&sysparm_limit=50", { headers: getHeaders() }),
 fetch("/api/now/table/u_bus?sysparm_display_value=all&sysparm_limit=50", { headers: getHeaders() }),
 fetch("/api/now/table/u_bus_stop?sysparm_query=u_isactive=true&sysparm_display_value=all&sysparm_limit=100", { headers: getHeaders() }),
 ]);
 const [routesData, busesData, stopsData] = await Promise.all([
 routesRes.json(),
 busesRes.json(),
 stopsRes.json(),
 ]);
 setRoutes(routesData.result || []);
 setBuses(busesData.result || []);
 setStops(stopsData.result || []);
 } catch (e: any) {
 setError("Failed to load form data. Please try again.");
 } finally {
 setLoading(false);
 }
 };
 fetchData();
 }, []);

 const handleSubmit = async () => {
 if (!description.trim()) {
 setError("Please enter a description.");
 return;
 }
 setError("");
 setSubmitting(true);

 const payload: Record<string, any> = {
 u_issue_type: issueTypeValue,
 u_short_description: `${typeLabel} Report`,
 u_description: `<p>${description}</p>`,
 u_severity: severity,
 };

 if (selectedRoute) payload.u_current_route = selectedRoute;
 if (selectedBus) payload.u_current_bus = selectedBus;
 if (selectedStop) payload.u_current_bus_stop = selectedStop;
 if (isRouteChange && requestedRoute) payload.u_requested_route = requestedRoute;
 if (isRouteChange && requestedStop) payload.u_requested_bus_stop = requestedStop;
 if (isSafetyConcern) payload.u_safety_concern_type = SAFETY_CONCERN_MAP[issueType || ""] || safetyConcernType;
 if (latitude !== null) payload.u_reported_latitude = latitude;
 if (longitude !== null) payload.u_reported_longitude = longitude;

 try {
 const postRes = await fetch("/api/now/table/u_transportation_case", {
 method: "POST",
 headers: getHeaders(),
 body: JSON.stringify(payload),
 });
 if (!postRes.ok) {
 const errBody = await postRes.json().catch(() => ({}));
 throw new Error(errBody?.error?.message || `HTTP ${postRes.status}`);
 }
 const postData = await postRes.json();
 const newSysId = getSysId(postData.result);

 // Fetch the record back to get BR-generated fields
 const getRes = await fetch(
 `/api/now/table/u_transportation_case/${newSysId}?sysparm_display_value=all`,
 { headers: getHeaders() }
 );
 const getData = await getRes.json();
 setCreatedCase(getData.result);
 setSubmitted(true);
 } catch (e: any) {
 setError(e.message || "Failed to submit report.");
 } finally {
 setSubmitting(false);
 }
 };

 if (loading) {
 return (
 <div style={{ padding: 16, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh" }}>
 <div style={{ width: 40, height: 40, border: "4px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
 <p style={{ marginTop: 16, color: "#666", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>Loading form data...</p>
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 );
 }

 if (submitted && createdCase) {
 const caseNumber = dv(createdCase.u_number) || "Submitted";
 const solutionResponse = dv(createdCase.u_solution_response);
 const state = dv(createdCase.u_state);

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 <div style={{ textAlign: "center", padding: "40px 16px" }}>
 <div style={{ fontSize: 56, marginBottom: 16 }}>✅</div>
 <h2 style={{ margin: "0 0 8px", fontSize: 22, color: "#1a1a1a" }}>Issue Reported!</h2>
 <p style={{ margin: "0 0 4px", fontSize: 14, color: "#666" }}>Case Number</p>
 <p style={{ margin: "0 0 16px", fontSize: 20, fontWeight: 700, color: "#0066cc" }}>{caseNumber}</p>
 {state && <p style={{ margin: "0 0 16px", fontSize: 13, color: "#555" }}>Status: {state}</p>}
 </div>

 {solutionResponse && (
 <div style={{ background: "linear-gradient(135deg, #e8f5e9 0%, #f1f8e9 100%)", borderRadius: 12, padding: 16, marginBottom: 20, border: "1px solid #c8e6c9" }}>
 <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
 <span style={{ fontSize: 18 }}>💡</span>
 <span style={{ fontSize: 14, fontWeight: 600, color: "#2e7d32" }}>Automated Response</span>
 </div>
 <p style={{ margin: 0, fontSize: 14, color: "#333", lineHeight: 1.5 }}>{solutionResponse}</p>
 </div>
 )}

 <button
 onClick={() => navigate("home")}
 style={{ width: "100%", padding: "14px 0", background: "#0066cc", color: "#fff", border: "none", borderRadius: 12, fontSize: 16, fontWeight: 600, cursor: "pointer" }}
 >
 Back to Home
 </button>
 <button
 onClick={() => navigate("requests")}
 style={{ width: "100%", padding: "14px 0", background: "transparent", color: "#0066cc", border: "1px solid #0066cc", borderRadius: 12, fontSize: 16, fontWeight: 600, cursor: "pointer", marginTop: 10 }}
 >
 View My Requests
 </button>
 </div>
 );
 }

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 {/* Header */}
 <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 20 }}>
 <button
 onClick={() => navigate("report")}
 style={{ background: "none", border: "none", padding: 4, cursor: "pointer", display: "flex", alignItems: "center" }}
 >
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#333" strokeWidth="2">
 <path d="M19 12H5M12 19l-7-7 7-7" />
 </svg>
 </button>
 <h1 style={{ margin: 0, fontSize: 20, fontWeight: 700, color: "#1a1a1a" }}>Report: {typeLabel}</h1>
 </div>

 {/* Issue type badge */}
 <div style={{ display: "inline-block", background: "#e3f2fd", color: "#1565c0", padding: "4px 12px", borderRadius: 16, fontSize: 12, fontWeight: 600, marginBottom: 20 }}>
 {issueTypeValue}
 </div>

 {error && (
 <div style={{ background: "#fdecea", color: "#c62828", padding: 12, borderRadius: 8, marginBottom: 16, fontSize: 13 }}>
 {error}
 </div>
 )}

 {/* Route dropdown */}
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Bus Route</label>
 <select
 value={selectedRoute}
 onChange={(e) => setSelectedRoute(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="">Select a route...</option>
 {routes.map((r) => (
 <option key={getSysId(r)} value={getSysId(r)}>
 {dv(r.u_route_name)} ({dv(r.u_start_location)} → {dv(r.u_end_location)})
 </option>
 ))}
 </select>
 </div>

 {/* Bus dropdown */}
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Bus</label>
 <select
 value={selectedBus}
 onChange={(e) => setSelectedBus(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="">Select a bus...</option>
 {buses.map((b) => (
 <option key={getSysId(b)} value={getSysId(b)}>
 {dv(b.u_bus_number)} — {dv(b.u_bus_status)}
 </option>
 ))}
 </select>
 </div>

 {/* Bus Stop dropdown */}
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Bus Stop</label>
 <select
 value={selectedStop}
 onChange={(e) => setSelectedStop(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="">Select a stop...</option>
 {stops.map((s) => (
 <option key={getSysId(s)} value={getSysId(s)}>
 {dv(s.u_stop_name)}
 </option>
 ))}
 </select>
 </div>

 {/* Safety Concern Type (conditional) */}
 {isSafetyConcern && (
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Safety Concern Type</label>
 <select
 value={safetyConcernType}
 onChange={(e) => setSafetyConcernType(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="unsafe_driving">Unsafe Driving</option>
 <option value="vehicle_condition">Vehicle Condition</option>
 <option value="security_concern">Security Concern</option>
 </select>
 </div>
 )}

 {/* Route Change - Requested Route (conditional) */}
 {isRouteChange && (
 <>
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Requested Route</label>
 <select
 value={requestedRoute}
 onChange={(e) => setRequestedRoute(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="">Select requested route...</option>
 {routes.map((r) => (
 <option key={getSysId(r)} value={getSysId(r)}>
 {dv(r.u_route_name)}
 </option>
 ))}
 </select>
 </div>
 <div style={{ marginBottom: 16 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Requested Stop</label>
 <select
 value={requestedStop}
 onChange={(e) => setRequestedStop(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="">Select requested stop...</option>
 {stops.map((s) => (
