 <p style={{ margin: 0, fontSize: 14, color: "#2e7d32", lineHeight: 1.6, fontWeight: 500 }}>
 {solutionResponse}
 </p>
 </div>
 )}

 {/* Main info card */}
 <div style={{ background: "#fff", borderRadius: 12, padding: 16, boxShadow: "0 2px 8px rgba(0,0,0,0.06)", border: "1px solid #f0f0f0", marginBottom: 16 }}>
 <h2 style={{ margin: "0 0 12px", fontSize: 17, fontWeight: 600, color: "#1a1a1a" }}>{shortDesc}</h2>

 <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 16 }}>
 <div>
