 <div style={{ fontSize: 14, fontWeight: 600, color: "#333" }}>{issueType}</div>
 </div>
 <div>
 <div style={{ fontSize: 11, color: "#888", marginBottom: 2 }}>Created</div>
 <div style={{ fontSize: 14, fontWeight: 500, color: "#333" }}>{createdOn}</div>
 </div>
 {currentRoute && (
 <div>
 <div style={{ fontSize: 11, color: "#888", marginBottom: 2 }}>Route</div>
 <div style={{ fontSize: 14, fontWeight: 500, color: "#333" }}>{currentRoute}</div>
 </div>
 )}
 {currentBus && (
 <div>
 <div style={{ fontSize: 11, color: "#888", marginBottom: 2 }}>Bus</div>
 <div style={{ fontSize: 14, fontWeight: 500, color: "#333" }}>{currentBus}</div>
 </div>
 )}
 {currentStop && (
 <div>
 <div style={{ fontSize: 11, color: "#888", marginBottom: 2 }}>Bus Stop</div>
 <div style={{ fontSize: 14, fontWeight: 500, color: "#333" }}>{currentStop}</div>
 </div>
 )}
 </div>

 {description && (
 <div style={{ borderTop: "1px solid #f0f0f0", paddingTop: 12 }}>
 <div style={{ fontSize: 11, color: "#888", marginBottom: 6 }}>Description</div>
 <div style={{ fontSize: 14, color: "#444", lineHeight: 1.5 }} dangerouslySetInnerHTML={{ __html: description }} />
 </div>
 )}
 </div>

 {/* Route Change info */}
 {isRouteChange && (requestedRoute || requestedStop) && (
 <div style={{ background: "#fff3e0", borderRadius: 12, padding: 16, marginBottom: 16, border: "1px solid #ffe0b2" }}>
 <div style={{ fontSize: 13, fontWeight: 600, color: "#e65100", marginBottom: 10 }}>🗺️ Route Change Request</div>
 {requestedRoute && (
 <div style={{ marginBottom: 6 }}>
 <span style={{ fontSize: 12, color: "#666" }}>Requested Route: </span>
 <span style={{ fontSize: 14, fontWeight: 600, color: "#333" }}>{requestedRoute}</span>
 </div>
 )}
 {requestedStop && (
 <div>
 <span style={{ fontSize: 12, color: "#666" }}>Requested Stop: </span>
 <span style={{ fontSize: 14, fontWeight: 600, color: "#333" }}>{requestedStop}</span>
 </div>
 )}
 </div>
 )}

 {/* Resolution notes */}
 {resolutionNotes && (
 <div style={{ background: "#f3e5f5", borderRadius: 12, padding: 16, marginBottom: 16, border: "1px solid #e1bee7" }}>
 <div style={{ fontSize: 13, fontWeight: 600, color: "#6a1b9a", marginBottom: 8 }}>📝 Resolution Notes</div>
 <p style={{ margin: 0, fontSize: 14, color: "#4a148c", lineHeight: 1.5 }}>{resolutionNotes}</p>
 </div>
 )}
 </div>
 );
}
