 <div className="ms-section-title" style={{ marginTop: "1rem" }}>Your Reports</div>
 <div className="ms-request-list">
 {lostItems.map((item) => (
 <div key={item.id} className="ms-request-card">
 <div className="ms-request-top">
 <span className="ms-request-id">{item.id}</span>
 <span className={`ms-badge ms-badge-${item.status === "searching" ? "yellow" : item.status === "found" ? "blue" : "green"}`}>
 {item.status.charAt(0).toUpperCase() + item.status.slice(1)}
 </span>
 </div>
 <div className="ms-request-title">{item.item}</div>
 <div className="ms-request-meta">
 <span>{item.route}</span>
 <span>{item.date}</span>
 </div>
 </div>
 ))}
 </div>
 </div>
 )}

 {showForm && (
 <div className="ms-form">
 <div className="ms-form-group">
 <label className="ms-label">Item Description</label>
 <input className="ms-input" placeholder="What did you lose?" />
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Bus Route</label>
 <select className="ms-select">
 <option value="">Select route...</option>
 <option value="42">Route 42 — Campus Express</option>
 <option value="15">Route 15 — North Loop</option>
 <option value="7">Route 7 — Downtown Shuttle</option>
 </select>
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Approximate Date & Time</label>
 <input className="ms-input" type="datetime-local" />
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Additional Details</label>
 <textarea className="ms-textarea" rows={3} placeholder="Color, brand, where you were sitting..." />
 </div>
 <div className="ms-form-actions">
 <Button label="Submit Report" onClick={() => setShowForm(false)} />
 </div>
 </div>
 )}
 </div>
