 transition: "left 0.2s ease",
 }} />
 </div>
 </div>

 {/* Geo Error */}
 {geoError && (
 <div style={{
 backgroundColor: "#fdf0f0",
 border: "1px solid #f5c6cb",
 borderRadius: "10px",
 padding: "12px 14px",
 marginBottom: "14px",
