 <div style={{ fontSize: "24px", fontWeight: 800, color: "#e63946" }}>{openCount}</div>
 <div style={{ fontSize: "11px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginTop: "4px" }}>Open</div>
 </div>
 <div style={{
 flex: 1,
